// services/rnd/avatarContract.test.js
//
// The server's check of an avatar record, against real records generated by the
// frontend on the pinned engine (test/rnd/fixtures/avatarContracts.json).
"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");

const contract = require("./avatarContract");
const fixtures = require("../../test/rnd/fixtures/avatarContracts.json");

const clone = (x) => JSON.parse(JSON.stringify(x));
const rehash = (c) => { c.contentSha256 = contract.sha256Json(c.content); return c; };
const refusal = (c) => {
  try { contract.verifyContract(c); return null; } catch (err) { return err.code; }
};

test("a real browser-generated record verifies, and the server's hash is the browser's", () => {
  for (const key of ["femaleM", "femaleMWiderHip"]) {
    const c = fixtures[key];
    assert.equal(contract.sha256Json(c.content), c.contentSha256);
    const out = contract.verifyContract(c);
    assert.equal(out.verdict, "fit-verified");
    assert.equal(out.engine.version, "0.2.1");
    assert.deepEqual(Object.keys(out.requestedMm), ["heightMm", "chestMm", "waistMm", "hipMm"]);
    assert.ok(out.bytes < contract.MAX_CONTRACT_BYTES);
  }
});

test("canonical JSON sorts keys at every depth, as the browser's does", () => {
  assert.equal(contract.canonicalJson({ b: 1, a: [{ d: 2, c: 1 }] }), '{"a":[{"c":1,"d":2}],"b":1}');
});

test("an edited record that kept its old hash is refused", () => {
  const c = clone(fixtures.femaleM);
  c.content.request.measurements.waistMm = 700;
  assert.equal(refusal(c), "CONTENT_HASH_MISMATCH");
});

test("a status the numbers deny is refused, even with a fresh hash", () => {
  const c = clone(fixtures.femaleM);
  const row = c.content.measurements.verified.find((r) => r.key === "waist");
  row.generatedMm = row.requestedMm + 12;
  row.differenceMm = 12;
  /* still claims pass */
  assert.equal(refusal(rehash(c)), "VERIFICATION_MISMATCH");
  row.status = "fail";
  /* row is now honest, the verdict is not */
  assert.equal(refusal(rehash(c)), "VERIFICATION_MISMATCH");
  c.content.verification = { ...c.content.verification, verdict: "failed", fitVerified: false };
  assert.equal(contract.verifyContract(rehash(c)).verdict, "failed");
});

test("Pass ≤5, Review ≤10, Fail beyond — the same rule the browser applies", () => {
  assert.equal(contract.statusFor(5), "pass");
  assert.equal(contract.statusFor(5.1), "review");
  assert.equal(contract.statusFor(-10), "review");
  assert.equal(contract.statusFor(10.1), "fail");
  assert.equal(contract.verdictFor(["pass", "review", "pass"]), "review");
  const c = clone(fixtures.femaleM);
  c.content.tolerance.passMm = 8;
  assert.equal(refusal(rehash(c)), "TOLERANCE_MISMATCH");
});

test("only the pinned engine, binary and pack are recorded", () => {
  const v = clone(fixtures.femaleM); v.content.engine.version = "latest";
  assert.equal(refusal(rehash(v)), "ENGINE_VERSION_MISMATCH");
  const p = clone(fixtures.femaleM); p.content.engine.packSha256 = "0".repeat(64);
  assert.equal(refusal(rehash(p)), "ENGINE_VERSION_MISMATCH");
});

test("units and axes are checked, not assumed", () => {
  const u = clone(fixtures.femaleM); u.content.frame.units = "cm";
  assert.equal(refusal(rehash(u)), "UNIT_MISMATCH");
  const f = clone(fixtures.femaleM); f.content.frame.forward = "-Z";
  assert.equal(refusal(rehash(f)), "COORDINATE_MISMATCH");
  const m = clone(fixtures.femaleM); m.content.request.measurements.heightMm = 168;
  m.content.measurements.verified.find((r) => r.key === "height").requestedMm = 168;
  assert.equal(refusal(rehash(m)), "UNIT_MISMATCH");
});

test("a record without a usable collision body is not an avatar", () => {
  const c = clone(fixtures.femaleM); delete c.content.collisionBody.bodies["standing-neutral"];
  assert.equal(refusal(rehash(c)), "COLLISION_BODY_FAILED");
  const h = clone(fixtures.femaleM); h.content.collisionBody.bodies["a-pose"].capsules[0].r += 1;
  assert.equal(refusal(rehash(h)), "CONTENT_HASH_MISMATCH");
});
